contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _seq, bytes32 _batcher, uint256 _overhead, uint256 _scalar) public payable {
        uint64 beforeNumber = c.number(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _seq, _batcher, _overhead, _scalar); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.number() == beforeNumber);
    }
    receive() external payable {}
}

