pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _seq, bytes32 _batcher, uint256 _overhead, uint256 _scalar) internal {
        uint64 beforeNumber;
        try c.number() returns (uint64 __r) { beforeNumber = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _seq, _batcher, _overhead, _scalar) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && c.number() == beforeNumber);
    }

    function testFuzz_run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _seq, bytes32 _batcher, uint256 _overhead, uint256 _scalar) public {
        _run(_number, _timestamp, _basefee, _hash, _seq, _batcher, _overhead, _scalar);
    }

    receive() external payable {}
}
